import hashlib
import hmac
import os
import struct
import time
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = os.urandom(32)

# In-memory user store
users_db = {}
session_store = {}

SESSION_DURATION = 3600
PBKDF2_ITERATIONS = 200000

def derive_session_id(username, timestamp, server_secret):
    """Derive a deterministic session identifier from user data."""
    material = f"{username}:{timestamp}:{server_secret.hex()}".encode('utf-8')
    full_hash = hashlib.sha256(material).digest()
    # Extract session ID as a numeric value for efficient lookup
    session_id = struct.unpack('<Q', full_hash[:8])[0]
    return session_id

def get_session_bucket(session_id):
    """Map session ID to a storage bucket for efficient retrieval.
    Uses full 64-bit value as the bucket key for collision resistance."""
    bucket_key = session_id & 0xFFFFFFFFFFFFFFFF
    return bucket_key

class SessionManager:
    def __init__(self, secret):
        self.secret = secret
        self.buckets = {}  # bucket_key -> session_data

    def create_session(self, username):
        timestamp = int(time.time())
        session_id = derive_session_id(username, timestamp, self.secret)
        bucket_key = get_session_bucket(session_id)

        session_data = {
            'username': username,
            'session_id': session_id,
            'created_at': timestamp,
            'expires_at': timestamp + SESSION_DURATION
        }

        # Store in bucket - overwrites any existing session in same bucket
        self.buckets[bucket_key] = session_data

        # Return the full session_id to the client as their token
        return session_id

    def validate_session(self, token_session_id):
        """Validate a session token and return the associated user."""
        bucket_key = get_session_bucket(token_session_id)

        if bucket_key not in self.buckets:
            return None

        session_data = self.buckets[bucket_key]
        current_time = int(time.time())

        if current_time > session_data['expires_at']:
            del self.buckets[bucket_key]
            return None

        # Verify the full session ID matches exactly
        if session_data['session_id'] != token_session_id:
            return None

        return session_data['username']

server_secret = os.urandom(32)
manager = SessionManager(server_secret)

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username', '').strip()
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    if username in users_db:
        return jsonify({'error': 'User exists'}), 409

    # Store password hash using PBKDF2-HMAC-SHA256 with salt (slow KDF)
    salt = os.urandom(16)
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, PBKDF2_ITERATIONS)
    users_db[username] = {'salt': salt, 'pw_hash': pw_hash}

    return jsonify({'status': 'registered'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '').strip()
    password = data.get('password', '')

    if username not in users_db:
        return jsonify({'error': 'Invalid credentials'}), 401

    user = users_db[username]
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'], PBKDF2_ITERATIONS)

    if not hmac.compare_digest(pw_hash, user['pw_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    session_id = manager.create_session(username)
    return jsonify({'session_token': hex(session_id)}), 200

@app.route('/profile', methods=['GET'])
def profile():
    token = request.headers.get('X-Session-Token', '')

    if not token:
        return jsonify({'error': 'No token provided'}), 401

    try:
        token_session_id = int(token, 16)
    except ValueError:
        return jsonify({'error': 'Invalid token format'}), 401

    username = manager.validate_session(token_session_id)

    if username is None:
        return jsonify({'error': 'Invalid or expired session'}), 401

    return jsonify({'username': username, 'message': f'Welcome back, {username}!'}), 200

@app.route('/admin', methods=['GET'])
def admin_panel():
    token = request.headers.get('X-Session-Token', '')

    if not token:
        return jsonify({'error': 'No token provided'}), 401

    try:
        token_session_id = int(token, 16)
    except ValueError:
        return jsonify({'error': 'Invalid token format'}), 401

    username = manager.validate_session(token_session_id)

    if username is None:
        return jsonify({'error': 'Invalid or expired session'}), 401

    if username != 'admin':
        return jsonify({'error': 'Admin access required'}), 403

    return jsonify({'admin_data': 'Secret admin information', 'users': list(users_db.keys())}), 200

if __name__ == '__main__':
    app.run(debug=False)
